import heapq

import heapq

def minimum_effort_path(heights):
    R, C = len(heights), len(heights[0])
    best = [[float('inf')] * C for _ in range(R)]
    best[0][0] = 0
    h = [(0, 0, 0)]
    while h:
        e, y, x = heapq.heappop(h)
        if (y, x) == (R - 1, C - 1):
            return e
        if e > best[y][x]:
            continue
        for yy, xx in ((y + 1, x), (y - 1, x), (y, x + 1), (y, x - 1)):
            if 0 <= yy < R and 0 <= xx < C:
                ne = max(e, abs(heights[yy][xx] - heights[y][x]))
                if ne < best[yy][xx]:
                    best[yy][xx] = ne
                    heapq.heappush(h, (ne, yy, xx))
    return 0

