int minimumEffortPath(vector<vector<int>>& H) {
    int R = H.size(), C = H[0].size(); vector<vector<int>> b(R, vector<int>(C, INT_MAX)); b[0][0] = 0;
    priority_queue<array<int,3>, vector<array<int,3>>, greater<>> h; h.push({0, 0, 0}); int d[5] = {1, 0, -1, 0, 1};
    while (!h.empty()) { auto [e, y, x] = h.top(); h.pop(); if (y == R - 1 && x == C - 1) return e; if (e > b[y][x]) continue;
        for (int k = 0; k < 4; k++) { int yy = y + d[k], xx = x + d[k + 1]; if (yy < 0 || yy >= R || xx < 0 || xx >= C) continue; int ne = max(e, abs(H[yy][xx] - H[y][x])); if (ne < b[yy][xx]) { b[yy][xx] = ne; h.push({ne, yy, xx}); } } }
    return 0;
}
